Review this Java code and find bugs: public static int calculateTotalAlternatingSum(int[] arr1, int[] arr2) {

    int totalSum = 0;

    for (int i = 0; i < arr1.length; i++) {

        if (i % 2 == 0) {
            totalSum += arr1[i] + arr2[i];
        } else {
            totalSum += arr1[i] - arr2[i];
        }
    }

    return totalSum;
}
